from pathlib import Path
import importlib.util,json,hashlib,zipfile,io
from PIL import Image
r=Path.cwd();s=r/'.local/step07-ci-required-body';f=s/'final';w=r/json.loads((f/'workspace.json').read_text())['workspace'];source=json.loads((f/'workspace.json').read_text())['source'];p=r/'.local/step07-r7-zip-fix/r7-original/probes/verify-zips.py';sp=importlib.util.spec_from_file_location('independent_r7_zip',p);mod=importlib.util.module_from_spec(sp);sp.loader.exec_module(mod);rows=[]
for mode in ['production','dev']:
 base=w/'.local/step07/browser'/mode
 assert (base/'first-export.zip').read_bytes()==(base/'history-export.zip').read_bytes()
 for q in sorted(base.glob('*.zip')):
  v=mod.verify(q);assert v['source']==source
  with zipfile.ZipFile(q)as z:
   assert z.testzip() is None;pngs={}
   for n in ['A1.png','A2.png']:
    image=Image.open(io.BytesIO(z.read(n)));image.load();assert image.mode=='RGBA'and image.size==(768,576);pngs[n]={'size':list(image.size),'mode':image.mode,'pixelSHA256':hashlib.sha256(image.tobytes()).hexdigest()}
  rows.append({'origin':str(q.relative_to(r)),'actual':v,'PillowIndependentDecoded':pngs})
assert len(rows)==6
(s/'downloads-independent.json').write_text(json.dumps({'source':source,'actualBrowserDownloads':6,'firstSecondRegistrationPositions':4,'distinctExportBuildIDs':len(set(x['actual']['exportBuildId'] for x in rows)),'historyByteSameFirst':True,'independentOracleOriginalSHA256':hashlib.sha256(p.read_bytes()).hexdigest(),'rows':rows},indent=2)+'\n');print('six actual browser ZIPs: strict independent directories/CRC/hash/profile/Source and12 PNG decodes valid; history byte same first')
